package cli

// new.go — ncoda new 模板脚手架（开放面：只依赖标准库）。:生成可直接 run / deploy 的最小 ncoda
// 工作流（或 agent）源文件。心智模型对齐可视化工作流工具:从一个可运行骨架开始,
// 而不是从空文件起步。

import (
	"fmt"
	"os"
	"path/filepath"

	"strings"
)

// workflowTemplate 是最小可运行工作流模板（start → llm → end）。
const workflowTemplate = `@language nodecoda/1
// %s.ncoda — generated by ncoda new.
// 可本地运行:ncoda run -p query=hello %s.ncoda
// 可部署:平台适配器随商业发行版提供（开源发行版只保证 run）

@mode workflow

const MODEL = "openai_api_compatible/gpt-5.4";

function main(string query) {
    let response = llm(MODEL, {
        "messages": [
            { "role": "system", "content": "You are a helpful assistant." },
            { "role": "user",   "content": query }
        ]
    });

    return response.text;
}
`

// agentTemplate 是最小可运行 agent 模板（带 tool 调用能力的对话循环）。
const agentTemplate = `@language nodecoda/1
// %s.ncoda — generated by ncoda new --mode agent.
// 运行:ncoda run -p query="帮我查一下天气" %s.ncoda

@mode agent
@agent { model: "openai_api_compatible/gpt-5.4", instruction: "你是助手" }

function main(string query) -> string {
    return run(query);
}
`

// projectConfigJSON 是 --project 模式生成的 config.json（示例 LLM 配置）。
// echo 工厂离线运行不需要 key;接真实模型时填入自己的 key（或 -openai-key / 环境变量）。
const projectConfigJSON = `{
  "llm": {
    "base_url": "https://api.openai.com/v1",
    "key": "",
    "model": "gpt-5.6-sol"
  }
}
`

// exampleHTTPManifest 是 --project 模式生成的示例 HTTP 插件 manifest
// （ncoda plugin add plugins/template/example_http.yaml 注册后可 run 使用）。
// 单一事实源:make_dist.sh 的 starter 项目由 ncoda new --project 生成,不再内嵌副本。
const exampleHTTPManifest = `id: example_http
type: http
server_url: https://api.example.com
tools:
  - name: hello
    method: GET
    path: /hello
    desc: example tool
    params:
      - name: name
        type: string
        in: query
        required: true
`

// NewMain 实现 `ncoda new [--mode workflow|agent] <name>`。
// 返回进程退出码:0 = 生成成功,1 = 运行时错误,2 = 用法错误。
func NewMain(args []string) int {
	mode := "workflow"
	project := false
	var name string
	for i := 0; i < len(args); i++ {
		switch {
		case args[i] == "--project" || args[i] == "-project":
			project = true
		case args[i] == "--mode" || args[i] == "-mode":
			if i+1 < len(args) {
				i++
				mode = args[i]
			}
		case args[i] == "--help" || args[i] == "-h":
			fmt.Fprint(Stderr, "usage: ncoda new [--mode workflow|agent] [--project] <name>\n")
			fmt.Fprint(Stderr, "  --project   生成完整项目目录（<name>/<name>.ncoda + config.json + plugins/ 示例插件）\n")
			return 0
		case strings.HasPrefix(args[i], "-"):
			fmt.Fprintf(Stderr, "ncoda new: unknown flag %q\n", args[i])
			return 2
		case name == "":
			name = args[i]
		default:
			fmt.Fprintf(Stderr, "ncoda new: unexpected extra argument %q\n", args[i])
			return 2
		}
	}
	if name == "" {
		fmt.Fprint(Stderr, "ncoda new: missing <name>\nusage: ncoda new [--mode workflow|agent] [--project] <name>\n")
		return 2
	}
	if strings.ContainsRune(name, os.PathSeparator) {
		fmt.Fprintf(Stderr, "ncoda new: name %q must be a plain file stem (no path separators)\n", name)
		return 2
	}
	if !ValidTemplateName(name) {
		fmt.Fprintf(Stderr, "ncoda new: name %q contains invalid characters (use [A-Za-z0-9_-])\n", name)
		return 2
	}
	if project {
		return NewProject(name, mode)
	}
	var body string
	switch mode {
	case "workflow":
		body = fmt.Sprintf(workflowTemplate, name, name)
	case "agent":
		body = fmt.Sprintf(agentTemplate, name, name)
	default:
		fmt.Fprintf(Stderr, "ncoda new: unknown mode %q (allowed: workflow, agent)\n", mode)
		return 2
	}
	target := name + ".ncoda"
	if _, err := os.Stat(target); err == nil {
		fmt.Fprintf(Stderr, "ncoda new: %s already exists (refusing to overwrite)\n", target)
		return 1
	}
	if err := os.WriteFile(target, []byte(body), 0o644); err != nil {
		fmt.Fprintf(Stderr, "ncoda new: %v\n", err)
		return 1
	}
	Out("created %s (%s template)\n", target, mode)
	Out("  run    : ncoda run -p query=hello %s\n", target)
	Out("  deploy : needs a platform adapter; the open distribution ships the runtime only\n")
	return 0
}

// NewProject 实现 `ncoda new --project <name>`:生成完整项目目录结构——
//
//	<name>/<name>.ncoda            可运行工作流/agent 源文件
//	<name>/config.json             LLM 示例配置（echo 工厂离线可跑;接真实模型时填 key）
//	<name>/plugins/template/      示例 HTTP 插件 manifest（ncoda plugin add 注册）
//
// 心智模型:解压 dist 包 → cd starter → ncoda run starter.ncoda 立即可跑;
// 正式建项目用 --project 生成到任意目录（模板与二进制同版本发布）。
func NewProject(name, mode string) int {
	var body string
	switch mode {
	case "workflow":
		body = fmt.Sprintf(workflowTemplate, name, name)
	case "agent":
		body = fmt.Sprintf(agentTemplate, name, name)
	default:
		fmt.Fprintf(Stderr, "ncoda new: unknown mode %q (allowed: workflow, agent)\n", mode)
		return 2
	}
	if _, err := os.Stat(name); err == nil {
		fmt.Fprintf(Stderr, "ncoda new: %s already exists (refusing to overwrite)\n", name)
		return 1
	}
	if err := os.MkdirAll(name, 0o755); err != nil {
		fmt.Fprintf(Stderr, "ncoda new: %v\n", err)
		return 1
	}
	files := []struct{ path, content string }{
		{filepath.Join(name, name+".ncoda"), body},
		{filepath.Join(name, "config.json"), projectConfigJSON},
		{filepath.Join(name, "plugins", "template", "example_http.yaml"), exampleHTTPManifest},
	}
	for _, f := range files {
		if err := os.MkdirAll(filepath.Dir(f.path), 0o755); err != nil {
			fmt.Fprintf(Stderr, "ncoda new: %v\n", err)
			return 1
		}
		if err := os.WriteFile(f.path, []byte(f.content), 0o644); err != nil {
			fmt.Fprintf(Stderr, "ncoda new: %v\n", err)
			return 1
		}
	}
	Out("created project %s/\n", name)
	Out("  run    : cd %s && ncoda run -p query=hello %s.ncoda\n", name, name)
	Out("  deploy : needs a platform adapter; the open distribution ships the runtime only\n")
	Out("  plugin : cd %s && ncoda plugin add plugins/template/example_http.yaml\n", name)
	return 0
}

// ValidTemplateName 限制生成文件名到安全字符集（避免路径注入/跨平台问题）。
func ValidTemplateName(name string) bool {
	if name == "" {
		return false
	}
	for _, r := range name {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '_', r == '-':
		default:
			return false
		}
	}
	return true
}
